  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Pacientes ambulatorios","Control puntual","Transporte","Sala general"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Característica: Pantalla LCD TFT a color 8.4\" (dato de ficha/catálogo o página Northern Meditec).","Configuración: SpO2+NIBP+ECG+TEMP (dato de ficha/catálogo o página Northern Meditec).","Característica: Batería recargable de iones de litio 15h (dato de ficha/catálogo o página Northern Meditec).","Opcional: Masimo/Nellcor SpO2, EtCO2, Temperatura rápida (dato de ficha/catálogo o página Northern Meditec).","Característica: Escáner de código de barras (dato de ficha/catálogo o página Northern Meditec)."],"beneficios_en":["Característica: Pantalla LCD TFT a color 8.4\" (per Northern Meditec catalog/page).","Configuración: SpO2+NIBP+ECG+TEMP (per Northern Meditec catalog/page).","Característica: Batería recargable de iones de litio 15h (per Northern Meditec catalog/page).","Opcional: Masimo/Nellcor SpO2, EtCO2, Temperatura rápida (per Northern Meditec catalog/page).","Característica: Escáner de código de barras (per Northern Meditec catalog/page)."],"valor_es":"Monitor Multiparámetro Acuarius Northern Meditec con especificaciones publicadas por el fabricante (https://en.northernmeditec.com/prodet/14.html), distribuida por IME.","valor_en":"Multi-parameter Monitor Acuarius by Northern Meditec with manufacturer-published specs (https://en.northernmeditec.com/prodet/14.html), supplied by IME.","preguntas_frecuentes_es":[{"q":"¿Qué modelo es el Monitor Multiparámetro Acuarius?","a":"Es el modelo Acuarius de Northern Meditec, referenciado en el catálogo IME y en la ficha del fabricante."},{"q":"¿Para qué áreas está indicado el Acuarius?","a":"Según catálogo: Pacientes ambulatorios, Control puntual, Transporte, Sala general."},{"q":"¿Qué configuración base declara el fabricante?","a":"Característica: Pantalla LCD TFT a color 8.4\"; Configuración: SpO2+NIBP+ECG+TEMP; Característica: Batería recargable de iones de litio 15h; Opcional: Masimo/Nellcor SpO2, EtCO2, Temperatura rápida"},{"q":"¿Dónde verifico la ficha técnica oficial?","a":"En la página del fabricante: https://en.northernmeditec.com/prodet/14.html. IME puede facilitar la documentación comercial del modelo Acuarius."},{"q":"¿Cómo cotizar el Acuarius con IME?","a":"Solicite cotización indicando el modelo exacto Northern Meditec y el área clínica de uso; IME confirma disponibilidad y soporte en Colombia."}],"preguntas_frecuentes_en":[{"q":"What model is the Multi-parameter Monitor Acuarius?","a":"It is Northern Meditec model Acuarius, listed in the IME catalog and manufacturer materials."},{"q":"Which care areas is Acuarius for?","a":"Per catalog: Pacientes ambulatorios, Control puntual, Transporte, Sala general."},{"q":"What base configuration does the manufacturer state?","a":"Característica: Pantalla LCD TFT a color 8.4\"; Configuración: SpO2+NIBP+ECG+TEMP; Característica: Batería recargable de iones de litio 15h; Opcional: Masimo/Nellcor SpO2, EtCO2, Temperatura rápida"},{"q":"Where is the official datasheet?","a":"Manufacturer page: https://en.northernmeditec.com/prodet/14.html. IME can provide commercial documentation for model Acuarius."},{"q":"How do I request a quote for Acuarius?","a":"Request a quote with the exact Northern Meditec model and clinical area; IME confirms availability in Colombia."}],"seo_keywords_es":["Monitor Multiparámetro Acuarius","Acuarius Northern Meditec","ficha técnica Acuarius","equipo médico Colombia","Acuarius IME"],"seo_keywords_en":["Multi-parameter Monitor Acuarius","Acuarius Northern Meditec","Acuarius datasheet","medical equipment Colombia"],"ficha_fabricante":{"fabricante":"Northern Meditec","idioma":"en","url_origen":"https://en.northernmeditec.com/prodet/14.html","descargada":null,"sin_pdf":true}}$j$::jsonb
